 const [models,setModels]=useState<ManagedModel[]>([]),[activeModelId,setActiveModelId]=useState(""),[deviceProfile,setDeviceProfile]=useState<DeviceProfile|null>(null),[modelPreflights,setModelPreflights]=useState<Record<string,ModelPreflight>>({}),[modelPreflightBusy,setModelPreflightBusy]=useState<string|null>(null),[modelDiscoveryBusy,setModelDiscoveryBusy]=useState(false),[modelDiscoveryNotice,setModelDiscoveryNotice]=useState(""),[modelDiscoveryError,setModelDiscoveryError]=useState(""),[modelCatalog,setModelCatalog]=useState<any[]>([]),[modelLoading,setModelLoading]=useState(false),[modelSelecting,setModelSelecting]=useState<string|null>(null),[modelActivationBusy,setModelActivationBusy]=useState<string|null>(null),[modelFilePath,setModelFilePath]=useState(""),[modelRegisterName,setModelRegisterName]=useState(""),[modelRegisterId,setModelRegisterId]=useState(""),[modelRegisterKind,setModelRegisterKind]=useState("chat"),[modelRegisterFormat,setModelRegisterFormat]=useState("litertlm"),[modelRegisterBusy,setModelRegisterBusy]=useState(false),[hubQuery,setHubQuery]=useState("litertlm"),[hubResults,setHubResults]=useState<HubModel[]>([]),[hubSearchBusy,setHubSearchBusy]=useState(false),[hubRepo,setHubRepo]=useState(""),[hubRevision,setHubRevision]=useState("main"),[hubFiles,setHubFiles]=useState<HubFile[]>([]),[hubFilesBusy,setHubFilesBusy]=useState(false),[hubDownloading,setHubDownloading]=useState<string|null>(null),[hubNotice,setHubNotice]=useState(""),[hubError,setHubError]=useState(""),[hubStatus,setHubStatus]=useState<any>(null),[hubTokenInput,setHubTokenInput]=useState(""),[hubTokenBusy,setHubTokenBusy]=useState(false),[hubTokenNotice,setHubTokenNotice]=useState(""),[cacheInventory,setCacheInventory]=useState<CacheInventory|null>(null),[cacheBusy,setCacheBusy]=useState(false),[cacheError,setCacheError]=useState(""),[snapshots,setSnapshots]=useState<Snapshot[]>([]),[auditVerification,setAuditVerification]=useState<AuditVerification|null>(null),[auditVerifying,setAuditVerifying]=useState(false),[decisionBusy,setDecisionBusy]=useState<string|null>(null);
